import { field, textarea, select, checkbox, htmlEscape, attrEscape, normalizeUrl } from "../tool-core.js";export default {form: `<div class="field-grid">${select({id: "osScenario",label: "Scenario",value: "body",options: [{ label: "Body (prevent pull-to-refresh)", value: "body" },{ label: "Modal / drawer overlay", value: "modal" },{ label: "Sidebar navigation", value: "sidebar" },{ label: "Horizontal carousel", value: "carousel" },{ label: "Custom", value: "custom" }]})}${select({id: "osBehavior",label: "Behavior",value: "contain",options: [{ label: "contain (stop chaining, keep bounce)", value: "contain" },{ label: "none (no chaining, no bounce)", value: "none" },{ label: "auto (browser default)", value: "auto" }]})}${select({id: "osAxis",label: "Axis",value: "both",options: [{ label: "both (x and y)", value: "both" },{ label: "x (horizontal only)", value: "x" },{ label: "y (vertical only)", value: "y" }]})}${field({ id: "osSelector", label: "Selector", value: "body", full: true })}</div>`,generate(root) {const scenario = root.querySelector("#osScenario").value;const behavior = root.querySelector("#osBehavior").value;const axis = root.querySelector("#osAxis").value;const presets = { body: "body", modal: ".modal-overlay", sidebar: ".sidebar", carousel: ".carousel-track", custom: ".overscroll-target" };const presetSelector = root.querySelector("#osSelector").value.trim();const selector = scenario === "custom" ? (presetSelector || ".overscroll-target") : presets[scenario];const prop = axis === "both" ? `overscroll-behavior: ${behavior};` : `overscroll-behavior-${axis}: ${behavior};`;const warnings = [];if (scenario === "body" && behavior === "none") warnings.push("Caution: overscroll-behavior: none on body disables pull-to-refresh entirely.");const warnText = warnings.length ? `\n\n/* ${warnings.join(" ")} */` : "";return { output: `${selector} {${prop}}${warnText}/* contain — stops scroll chaining but keeps visual bounce.none — prevents scroll chaining and bounce effects.auto — browser default overscroll behavior. */` };}};